using UnityEngine;using UnityEditor;using System.Linq;public static class FlameShaderCheck{public static string Run(){var s=AssetDatabase.LoadAssetAtPath<Shader>("Assets/Resources/Presentation/EmberFlame.shader");var errors=ShaderUtil.GetShaderMessages(s).Where(m=>m.severity.ToString()=="Error").Select(m=>m.message);return "supported="+s.isSupported+"; errors="+string.Join(";",errors);}}
